"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[55613],{38913:e=>{e.exports=JSON.parse('{"id":"2026-08-11-rcs-rich-card-media-height-optional","date":"2026-08-11","products":["Connect","APIs"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS rich card media height documented as optional","excerpt":"The media.height field on RCS rich cards was documented as if a value were always required. It is now clarified as optional, defaulting to SHORT when omitted.","hasArticle":true,"bodyHtml":"<p>The <code>media.height</code> field on RCS rich cards was documented as if a value were always required. It is now clarified as <strong>optional</strong>, defaulting to <code>SHORT</code> when omitted.</p>\\n<h2>What changed</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Field</th>\\n<th>Type</th>\\n<th>Description</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><code>media.height</code></td>\\n<td>string</td>\\n<td><code>SHORT</code>, <code>MEDIUM</code>, or <code>TALL</code>. Vertical cards only. Optional \u2014 defaults to <code>SHORT</code> when omitted.</td>\\n</tr>\\n</tbody></table>\\n<p>This applies to vertical rich cards sent through the Messaging API. Horizontal cards are unaffected, since <code>media.height</code> only applies to the vertical orientation.</p>\\n<h2>Where to look</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/rcs/message-types\\">RCS message types and samples</a> \u2014 updated rich card field reference</li>\\n<li><a href=\\"/connect/reference/send-message\\">Send message \u2014 API reference</a></li>\\n<li><a href=\\"/connect/reference/send-message-many\\">Send message batch \u2014 API reference</a></li>\\n</ul>\\n"}')}}]);